// Published sample XML (samples/<RT>_sample.xml + /cra-xml-samples): generated by the real pipeline from
// templates/<RT>_Sample.csv with the in-app demo filing details, embedded verbatim on the page, and valid
// against the CRA XSD version the page states.
// Regenerate after an intended XML change: UPDATE_SAMPLES=1 node tests/xml-samples.test.js
// XSDs: CRA_XSD_<version> env var (e.g. CRA_XSD_1_26_3=/path/to/xsd), else /tmp/cra_xsd (1-26-3) or /tmp/cra_xsd_2027 (1-27-1).
const assert = require('assert');
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');
const { createApp, fileToXML, ROOT } = require('./harness');

const TYPES = ['T4', 'T5018', 'NR4', 'T1204'];
const PAGE = path.join(ROOT, 'cra-xml-samples.html');
const URL = 'https://taxxml.ca/cra-xml-samples';
const XML_SPECS = 'https://www.canada.ca/en/revenue-agency/services/e-services/filing-information-returns-electronically-t4-t5-other-types-returns-overview/xml-specs.html';
const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const demo = rt => JSON.parse(JSON.stringify(createApp().run(`demoDetails('${rt}')`)));
const sampleXml = rt => fileToXML(rt, `${rt}_Sample.csv`, fs.readFileSync(path.join(ROOT, 'templates', `${rt}_Sample.csv`)), demo(rt)).xml;

let html = fs.readFileSync(PAGE, 'utf8');
for (const rt of TYPES) {
  const file = path.join(ROOT, 'samples', `${rt}_sample.xml`);
  const xml = sampleXml(rt);
  const pre = new RegExp(`(<pre id="xml-${rt.toLowerCase()}"[^>]*><code>)([\\s\\S]*?)(</code></pre>)`);
  if (process.env.UPDATE_SAMPLES) {
    fs.writeFileSync(file, xml);
    html = html.replace(pre, (_, a, __, c) => a + esc(xml) + c);
    fs.writeFileSync(PAGE, html);
  }
  assert.strictEqual(fs.readFileSync(file, 'utf8'), xml, `samples/${rt}_sample.xml is stale: UPDATE_SAMPLES=1`);
  assert(pre.test(html), `page embeds <pre id="xml-${rt.toLowerCase()}">`);
  assert.strictEqual(html.match(pre)[2], esc(xml), `page XML for ${rt} matches the file`);
  assert(html.includes(`href="/samples/${rt}_sample.xml" download`), `${rt}: raw file downloadable`);
  assert(/demo/i.test(xml), `${rt}: sample is visibly demo data`);
  const slug = `${rt.toLowerCase()}-xml-generator`;
  const landing = fs.readFileSync(path.join(ROOT, `${slug}.html`), 'utf8');
  assert(landing.includes(`href="/cra-xml-samples#${rt.toLowerCase()}"`), `${slug} links its sample XML`);
  assert(landing.includes(`href="/?return=${rt}&amp;sample=1#converter"`), `${slug} has the one-click sample link`);
}

// SEO basics, same pattern as the generator pages
assert(/<title>[^<]*CRA XML[^<]*<\/title>/.test(html), 'title mentions CRA XML');
assert(/<meta name="description" content="[^"]{50,160}">/.test(html), 'meta description, 50-160 chars');
assert(html.includes(`<link rel="canonical" href="${URL}">`) && html.includes(`<meta property="og:url" content="${URL}">`), 'canonical + og:url');
assert(html.includes("gtag('config', 'G-E2F5Q3RZVH')"), 'same GA4 tag');
assert(html.match(/<div id="disclaimer"[^>]*>([\s\S]*?)<\/div>/)[1].includes(`href="${XML_SPECS}"`), 'disclaimer links CRA xml-specs');
assert(html.match(/<section id="liability">([\s\S]*?)<\/section>/)[1].includes('href="/terms"'), 'liability links /terms');
assert(fs.readFileSync(path.join(ROOT, 'sitemap.xml'), 'utf8').includes(`<loc>${URL}</loc>`), 'in sitemap.xml');
assert(fs.readFileSync(path.join(ROOT, 'index.html'), 'utf8').includes('href="/cra-xml-samples"'), 'linked from index.html');

// The schema version is stated once, and the XML is validated against exactly that version.
const versions = [...html.matchAll(/<strong id="sample-schema">([\d-]+)<\/strong>/g)].map(m => m[1]);
assert.strictEqual(versions.length, 1, 'schema version stated in exactly one place');
const version = versions[0];
const xsdDir = process.env[`CRA_XSD_${version.replace(/-/g, '_')}`] || { '1-26-3': '/tmp/cra_xsd', '1-27-1': '/tmp/cra_xsd_2027' }[version];
const py = `
import sys
from lxml import etree
d = sys.argv[1]
for rt, f in zip(sys.argv[2::2], sys.argv[3::2]):
    s = etree.XMLSchema(etree.parse(f'{d}/T619_{rt}.xsd'))
    if not s.validate(etree.parse(f)):
        print(rt, s.error_log); sys.exit(1)
`;
let skip = '';
if (!xsdDir || !fs.existsSync(path.join(xsdDir, 'T619_T4.xsd'))) skip = `CRA XSD ${version} not found (set CRA_XSD_${version.replace(/-/g, '_')})`;
else try { execFileSync('python3', ['-I', '-c', 'import lxml'], { stdio: 'ignore' }); } catch { skip = 'python3 with lxml not available'; }
if (skip) {
  console.warn(`\n!!! xml-samples.test.js: SKIPPED XSD VALIDATION: ${skip} !!!\n`);
} else {
  const args = TYPES.flatMap(rt => [rt, path.join(ROOT, 'samples', `${rt}_sample.xml`)]);
  execFileSync('python3', ['-I', '-c', py, xsdDir, ...args], { stdio: 'inherit' });
}
console.log(`xml-samples.test.js: ${TYPES.length} samples in sync${skip ? '' : `, valid against CRA schema ${version}`}`);
